        private static void doEcoute(Object data) {
            // thread for listening to customer requests
            try {
                // create the service
                service = new TcpListener(IPAddress.Any, port);
                 // launch it
                service.Start();
                // the server is active
                actif = true;
                 // follow-up
                Console.WriteLine("Serveur de calcul d'impôt lancé sur le port {0}", port);
                 // customer service loop
                TcpClient tcpClient = null;
                 // customer no
                int numClient = 0;
                 // endless loop
                while (true) {
                    // waiting for a customer
                    tcpClient = service.AcceptTcpClient();
                    // the service is provided by another task
                    ThreadPool.QueueUserWorkItem(doService, new Client() { CanalTcp = tcpClient, NumClient = numClient });
                     // next customer
                    numClient++;
                }
            } catch (Exception ex) {
                // we report the error
                Console.WriteLine("L'erreur suivante s'est produite sur le serveur : {0}", ex.Message);
            }
        }

         // customer info
        internal class Client {
             public TcpClient CanalTcp { get; set        ; } // customer liaison
             public int NumClient { get; set            ; } // customer no
}
</code></pre> <p>Dieser Code ähnelt dem des in Abschnitt 11.6.1 behandelten Echo-Servers. Wir gehen nur auf die Unterschiede ein:</p> <ul> <li>Zeile 7: Der Listening-Dienst wurde gestartet   </li> <li>Zeile 9: Es wird vermerkt, dass der Dienst nun aktiv ist   </li> </ul> <p>Zeile 21: Kunden werden von Service-Threads bedient, die die Funktion „doService“ ausführen:</p> <pre><code>
private static void doService(Object infos) {
            // the customer is picked up and served
            Client client = infos as Client;
            // renders service to the customer
            Console.WriteLine("Début du service au client {0}", client.NumClient);
             // operation link TcpClient
            try {
                using (TcpClient tcpClient = client.CanalTcp) {
                    using (NetworkStream networkStream = tcpClient.GetStream()) {
                        using (StreamReader reader = new StreamReader(networkStream)) {
                            using (StreamWriter writer = new StreamWriter(networkStream)) {
                                 // unbuffered output stream
                                writer.AutoFlush = true;
                                // send a welcome message to the customer
                                writer.WriteLine("Bienvenue sur le serveur de calcul de l'impôt");
                                // loop read request/write response
                                string demande = null;
                                bool serviceFini = false;
                                while (!serviceFini &amp;&amp; (demande = reader.ReadLine()) != null) {
                                     // console monitoring
                                    if (echo) {
                                        Console.WriteLine("&lt;--- Client {0} : {1}", client.NumClient, demande);
                                    }
                                     // demand analysis
                                    demande = demande.Trim().ToLower();
                                    // empty request?
                                    if (demande.Length == 0) {
                                        // erroneous request
                                        writeClient(writer,client.NumClient,"Commande non reconnue. Utilisez la commande aide.");
                                        return;
                                    }

                                    // demand is broken down into fields
                                    string[] champs = Regex.Split(demande, @"\s+");
                                     // analysis
                                    switch (champs[0].ToLower()) {
                                        case "aide":
                                            writeClient(writer, client.NumClient, "Commandes acceptées\n1-aide\n2-impot marié(O/N) nbEnfants salaireAnnuel\n3-aurevoir");
                                            break;
                                        case "impot":
                                            // tax calculation
                                            writeClient(writer, client.NumClient, calculImpot(writer, client.NumClient, champs));
                                            break;
                                        case "aurevoir":
                                            serviceFini = true;
                                            writeClient(writer, client.NumClient, "Au revoir...");
                                            break;
                                        default:
                                            writeClient(writer, client.NumClient, "Commande non reconnue. Utilisez la commande aide.");
                                            break;
                                    }
                                }
                            }
                        }
                    }
                }
            } catch (Exception e) {
                // error
                Console.WriteLine("L'erreur suivante s'est produite lors du service au client {0} : {1}", client.NumClient, e.Message);
            } finally {
                Console.WriteLine("Fin du service au client {0}", client.NumClient);
            }
        }

        private static void writeClient(StreamWriter writer, int numClient, string message) {
             // echo console ?
            if (echo) {
                Console.WriteLine("---&gt; Client {0} : {1}", numClient, message);
            }
             // send msg to customer
            writer.WriteLine(message);
}
</code></pre> <p>Auch hier ähnelt der Code dem des in Abschnitt 11.6.1 behandelten Echo-Servers. Wir gehen nur auf die Unterschiede ein:</p> <ul> <li>Zeile 15: Sobald der Client verbunden ist, sendet der Server eine Willkommensnachricht.   </li> <li>Zeilen 19–52: Die Schleife zum Lesen der Kundenbefehle. Die Schleife endet, wenn der Kunde „goodbye“ sendet.   </li> <li>Zeile 27: Fall einer leeren Bestellung   </li> <li>Zeile 34: Die Anfrage wird zur Analyse in Felder zerlegt   </li> <li>Zeile 37: Bestellhilfe: Der Kunde fordert eine Liste der zulässigen Bestellungen an   </li> <li>Zeile 40: Steuerberechnung: Der Client fordert eine Steuerberechnung an. Wir antworten mit der von der Funktion `calculImpot` zurückgegebenen Nachricht, auf die wir gleich näher eingehen werden.   </li> <li>Zeile 44: order goodbye: Der Kunde gibt an, dass er fertig ist.   </li> <li>Zeile 45: Wir bereiten uns darauf vor, die Leseschleife der Kundenanfragen (Zeilen 19–52) zu verlassen   </li> <li>Zeile 46: Wir antworten dem Kunden mit einer Abschiedsnachricht   </li> <li>Zeile 48: Eine fehlerhafte Bestellung. Eine Fehlermeldung wird an den Kunden gesendet.   </li> </ul> <p>Die Berechnung der Bestellabwicklungssteuer erfolgt durch das folgende Programm:</p> <pre><code>
private static string calculImpot(StreamWriter writer, int numClient, string[] champs) {
             // request calculation married(Y/N) nbEnfants salaireAnnuel
             // 4 fields are required
            if (champs.Length != 4) {
                return "Commande calcul incorrecte. Utilisez la commande aide.";
            }
             // fields [1]
            string marié = champs[1];
            if (marié != "o" &amp;&amp; marié != "n") {
                return "Commande calcul incorrecte. Utilisez la commande aide.";
            }
             // fields [2]
            int nbEnfants;
            if (!int.TryParse(champs[2], out nbEnfants)) {
                return "Commande calcul incorrecte. Utilisez la commande aide.";
            }
             // fields [3]
            int salaireAnnuel;
            if (!int.TryParse(champs[3], out salaireAnnuel)) {
                return "Commande calcul incorrecte. Utilisez la commande aide.";
            }
             // that's it - tax calculation
            int impot = 0;
            try {
                impot = metier.CalculerImpot(marié == "o", nbEnfants, salaireAnnuel);
                return impot.ToString();
            } catch (Exception ex) {
                return ex.Message;
            }
        }
</code></pre> <ul> <li>Zeile 1: Die Methode erhält das Array der Befehlsfelder als dritten Parameter tax. Bei korrekter Formulierung hat es die Form married tax nbEnfants salaireAnnuel. Das Ergebnis der Methode ist die Antwort, die an den Client gesendet werden soll.   </li> <li>Zeile 4: Überprüfen, ob der Befehl 4 Felder hat   </li> <li>Zeile 8: Überprüfen, ob „married“ gültig ist   </li> <li>Zeile 14: Überprüfen, ob „nbEnfants“ gültig ist   </li> <li>Zeile 19: Überprüfen, ob „salaireAnnuel“ gültig ist   </li> <li>Zeile 25: tax wird mithilfe von CalculerImpot der Ebene [metier] berechnet. Beachten Sie, dass diese Ebene in einer DLL gekapselt ist.   </li> <li>Zeile 26: Wenn die [metier]-Schicht ein Ergebnis zurückgegeben hat, wird dieses an den Kunden zurückgegeben.   </li> <li>Zeile 28: Wenn die [metier]-Schicht eine Ausnahme ausgelöst hat, wird die Ausnahmemeldung an den Client zurückgegeben.   </li> </ul> <p></p>
